CREATE TABLE IF NOT EXISTS radcheck (id INTEGER PRIMARY KEY AUTOINCREMENT, username VARCHAR(64) NOT NULL, attribute VARCHAR(64) NOT NULL, op CHAR(2) NOT NULL, value VARCHAR(253) NOT NULL);
CREATE TABLE IF NOT EXISTS radreply (id INTEGER PRIMARY KEY AUTOINCREMENT, username VARCHAR(64) NOT NULL, attribute VARCHAR(64) NOT NULL, op CHAR(2) NOT NULL, value VARCHAR(253) NOT NULL);
CREATE TABLE IF NOT EXISTS radacct (radacctid INTEGER PRIMARY KEY AUTOINCREMENT, sessionid VARCHAR(64) NOT NULL, username VARCHAR(64) NOT NULL, nasipaddress VARCHAR(39) NOT NULL, nasportid VARCHAR(32), acctstarttime DATETIME, acctstoptime DATETIME, acctinputoctets BIGINT DEFAULT 0, acctoutputoctets BIGINT DEFAULT 0, acctsessiontime INTEGER DEFAULT 0, acctterminatecause VARCHAR(32) DEFAULT '');
CREATE TABLE IF NOT EXISTS radpostauth (id INTEGER PRIMARY KEY AUTOINCREMENT, username VARCHAR(64) NOT NULL, pass_reply VARCHAR(64) NOT NULL, authdate DATETIME NOT NULL);
